import {destination} from './moneybread/destinations.js';
import {renderCity,attachCity,applyCity,canOpen,currentLevel,noteLesson,validCity,freshCity} from './moneybread/index.js';
import {installDrag} from './drag.js';
import {visualMission,playAction,dropAction,littleBase} from './play.js';
import {missions,badges} from './content.js';
import {newGame,begin,choose,resolve,finish,rank,nextRank,netWorth,ranks} from './engine.js';
import {load,save,clear,storageWarning} from './persistence.js';
import {setMusic,sound} from './audio.js';
import {characters,castIds,portrait,crewHeroMarkup} from './characters.js';
import {FinancialRunner} from './runner.js';
import {runnerConfig,runnerLessons} from './runner-config.js';
import {markLessonCompleted,markLessonStarted,openRunner,recordRunnerResult,runnerComparison,runnerProgress} from './runner-state.js';
import {studentSummary} from './teacher.js';
import {buildCity,cityBuilderMarkup,cityBuildCelebrationMarkup} from './city.js';
import {arcadeLeaders,loadArcadeScores,recordArcadeScore} from './arcade-scores.js';
const cityUI={view:'city',district:'school',reset:false};
function ensureCareer(profile){if(!profile||profile.mode==='arcade')return profile;try{return attachCity(profile);}catch(error){return {...profile,cityLoadError:error.message};}}
const app=document.querySelector('#app');let careerProfile=ensureCareer(load());let p=careerProfile;let showingHome=true;let arcadeScores=loadArcadeScores();let tab='operations';let resetting=false;let selectedToken=null;let suppressClickUntil=0;let activeTrace=null;let runnerGame=null;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function progress(){const next=nextRank(p.xp);const current=ranks.filter(r=>p.xp>=r[1]).at(-1);const pct=next?Math.min(100,(p.xp-current[1])/(next[1]-current[1])*100):100;return `<div class="xp-row"><span>${p.xp} XP</span><span>${next?`${next[1]-p.xp} TO ${next[0].toUpperCase()}`:'TOP RANK'}</span></div><div class="bar" role="progressbar" aria-label="Rank progress" aria-valuenow="${Math.round(pct)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div>`;}
function header(){const arcade=p.mode==='arcade';return `<header><a class="brand" href="./" aria-label="Money Ops home"><span class="brand-mark">M<span>↗</span></span><span><small>FINANCIAL FREEDOM</small><b>MONEY OPS<span class="version"> / 46.3</span></b></span></a><div class="header-right"><span class="system ${arcade?'arcade-unsaved':''}"><i></i> ${arcade?'ARCADE MODE · NOT SAVED':'CAREER SAVED'}</span>${button('HOME','site-home','home-nav-button')}${button(arcade?'ARCADE LEVELS':'PLAY ARCADE','arcade-open-header','arcade-nav-button')}${button(p.muted?'SOUND OFF':'SOUND ON','mute','utility',`aria-pressed="${!p.muted}" aria-label="${p.muted?'Enable':'Mute'} sound"`)}</div></header>`;}
function playerPortrait(className='',id=p.avatar){return characters[id]?portrait(id,className):`<span class="avatar">${escape(id)}</span>`;}
function runnerCharacterId(){return castIds.includes(p?.avatar)?p.avatar:'maya';}
const bonusItems=[{id:'boots',name:'BOOST BOOTS',price:5,icon:'⇧',detail:'Jump higher.'},{id:'magnet',name:'COIN MAGNET',price:10,icon:'◎',detail:'Pull coins closer.'},{id:'companion',name:'PENNY THE MONEY DRAGON',price:15,icon:'🐲',detail:'Your original Money Ops sidekick blocks one hit.'}];
const arcadeIntensities=[{id:'rookie',label:'ROOKIE',level:0,multiplier:.68,detail:'Slow and steady. The pace stays slow.'},{id:'intermediate',label:'INTERMEDIATE',level:1,multiplier:1,detail:'Standard speed. The pace grows every 20 coins.'},{id:'expert',label:'EXPERT',level:1.5,multiplier:1.5,detail:'1.5× speed for a bigger challenge.'}];
function arcadeIntensity(){return arcadeIntensities.find(item=>item.id===p?.arcadeIntensity)||arcadeIntensities[1];}
function arcadeFooter(){const arcade=p?.mode==='arcade';return `<footer class="global-arcade-footer"><span><b>ARCADE MODE</b> · ${arcade?'TOWN TEMPORARY · TOP SCORES KEPT':'ALL 32 LEVELS · ANY CHARACTER'}</span>${button(arcade?'ARCADE LEVELS':'PLAY ARCADE MODE',arcade?'arcade-back':'arcade-open','arcade-nav-button')}</footer>`;}
function arcadeLeaderboardMarkup(lessonId=null,limit=5){const leaders=arcadeLeaders(arcadeScores,lessonId,limit);return `<section class="arcade-leaderboard" aria-label="${lessonId?`Level ${lessonId}`:'Arcade'} top scores"><div class="section-title"><h2>${lessonId?`LEVEL ${String(lessonId).padStart(2,'0')} TOP SCORES`:'ARCADE TOP SCORES'}</h2><span>INITIALS · SCORE · LEVEL</span></div>${leaders.length?`<ol>${leaders.map(entry=>`<li><b>${escape(entry.initials)}</b><strong>${entry.score.toLocaleString()}</strong><span>LEVEL ${String(entry.lessonId).padStart(2,'0')}</span></li>`).join('')}</ol>`:'<p>Finish an Arcade run and enter your initials to claim the first top score.</p>'}</section>`;}
function arcadeScorePanel(config,result){const recorded=p.runnerSession?.scoreRecorded,leaders=arcadeLeaders(arcadeScores,config.lessonId,10),best=leaders[0]?.score||0,newTop=result.score>best;return `<section class="arcade-score-entry"><div><span class="eyebrow">${recorded?'TOP SCORE SAVED!':newTop?'NEW TOP SCORE READY!':'SAVE YOUR BEST RUN'}</span><h2>${result.score.toLocaleString()} POINTS</h2><p>Enter two or three initials. Only your best score for this level stays on this device.</p></div>${recorded?`<div class="score-recorded">✓ ${escape(p.runnerSession.scoreInitials)} SAVED TO THE TOP SCORES</div>`:`<form id="arcade-score-form"><label for="arcade-initials">YOUR INITIALS</label><input id="arcade-initials" name="initials" maxlength="3" minlength="2" pattern="[A-Za-z0-9]{2,3}" autocomplete="off" required placeholder="ABC" aria-label="Two or three initials"><button class="primary" type="submit">KEEP MY TOP SCORE →</button></form>`}</section>${arcadeLeaderboardMarkup(config.lessonId,5)}`;}

function newArcadeProfile(avatar='jordan'){
 return {...newGame('Arcade Player',castIds.includes(avatar)?avatar:'jordan'),mode:'arcade',screen:'arcade',arcadeIntensity:'intermediate',runnerSession:null,active:null};
}
function arcadeHub(){
 const cityBuilder=cityBuilderMarkup(p,button,escape);
 return `${header()}<main id="main" class="arcade-hub" tabindex="-1"><section class="arcade-warning" role="status"><b>ARCADE MODE · PROGRESS IS NOT SAVED</b><span>Play any runner level with any character. Town construction, coins, and XP reset when you leave Arcade Mode. Initials and top scores stay on this device. Your Career Mode file is not changed.</span></section><div class="arcade-heading"><div><span class="eyebrow">ALL 32 LEVELS UNLOCKED</span><h1>CHOOSE. RUN. LEARN THE WORDS.</h1></div>${button(careerProfile?'RETURN TO SAVED CAREER':'BACK TO START','arcade-exit','secondary')}</div>${arcadeLeaderboardMarkup()}<section class="arcade-character-panel"><div><span class="eyebrow">1 · CHOOSE ANY CHARACTER</span><h2>${escape(characters[p.avatar]?.name||'Kanyon')} IS READY</h2></div><div class="arcade-character-grid">${castIds.map(id=>`<button class="arcade-character ${p.avatar===id?'selected':''}" data-action="arcade-character-${id}" aria-pressed="${p.avatar===id}">${portrait(id,'arcade-character-image')}<b>${characters[id].name}</b><small>${characters[id].role}</small></button>`).join('')}</div></section><section class="arcade-intensity-panel"><span class="eyebrow">2 · CHOOSE RUN INTENSITY</span><h2>HOW FAST SHOULD THIS RUN FEEL?</h2><div class="arcade-intensity-grid">${arcadeIntensities.map(item=>`<button class="arcade-intensity ${arcadeIntensity().id===item.id?'selected':''}" data-action="arcade-intensity-${item.id}" aria-pressed="${arcadeIntensity().id===item.id}"><span>LEVEL ${item.level}</span><b>${item.label}</b><small>${item.detail}</small></button>`).join('')}</div></section><section class="arcade-time-panel coin-goal-panel"><span class="eyebrow">3 · COMPLETE THE COIN GOAL</span><h2>LEVEL 1: 200 COINS, THEN KEEP RUNNING</h2><p>Level 1 has a 200-coin goal and continues while lives remain. Collect hearts for extra lives, or finish to bank rewards. Other levels target 100 coins. ${arcadeIntensity().id==='rookie'?'Rookie pace stays slow for the full run. Intermediate and Expert rise every 20 coins.':'The pace rises one speed stage every 20 coins.'} A vocabulary stream explains lesson words as you collect rewards and clear hazards.</p></section>${cityBuilder}<section class="arcade-level-section"><div class="section-title"><h2>4 · PICK ANY LEVEL</h2><span>NO LOCKS · NO SAVING</span></div><div class="arcade-level-grid">${runnerLessons.map(level=>{const config=runnerConfig(level.lessonId,'pre');return `<article class="arcade-level-card" style="--arcade-accent:${config.environmentData.accent}"><div><span>LEVEL ${String(level.lessonId).padStart(2,'0')}</span><b>${missions[level.lessonId-1].icon}</b></div><h3>${escape(level.title)}</h3><small>${escape(config.environmentData.name)}</small><p><strong>VOCABULARY:</strong> ${config.vocabulary.slice(0,5).map(item=>escape(item.term)).join(' · ')}</p>${button(`PLAY LEVEL ${String(level.lessonId).padStart(2,'0')} →`,`arcade-level-${level.lessonId}`,'primary')}</article>`;}).join('')}</div></section><footer class="arcade-footer"><div><b>ARCADE MODE IS TEMPORARY</b><span>Initials and top scores stay on this device. Town progress and rewards remain temporary and never change Career Mode.</span></div>${button('ARCADE LEVELS','arcade-back','arcade-nav-button')}</footer></main>`;
}
function profile(){return `<aside class="profile panel" style="--player-accent:${p.playerStyle?.accent||'#d9f577'}"><div class="eyebrow">YOUR CAREER HERO <span>${escape(p.playerStyle?.emblem||'◈')}</span></div><div class="identity">${playerPortrait('profile-character')}<div><h2>${escape(p.name)}</h2><span class="rank">${rank(p.xp)}</span></div></div>${progress()}<div class="profile-metrics"><span>LESSONS DONE<b>${p.completed.length} <em>/ ${missions.length}</em></b></span><span>CAREER JOURNEY<b>32 <em>levels</em></b></span></div><div class="aside-note"><span class="tiny-icon">${escape(p.playerStyle?.emblem||'◈')}</span><p>Your career starts at $0.<br><strong>Build value, savings, and investments.</strong></p></div><details class="rank-details"><summary>See all ranks</summary><div class="rank-ladder">${ranks.map(([r,x])=>`<div class="${p.xp>=x?'reached':''}"><span>${p.xp>=x?'◆':'◇'}</span>${r}<small>${x} XP</small></div>`).join('')}</div></details>${button('Career profile & save','profile','text-button')}</aside>`;}
function title(){const colors=['#d9f577','#54c7de','#ffcf65','#ef7594','#a98cff','#70c483'];return `<div class="title-screen"><div class="title-nav"><span class="eyebrow">POLARIS VILLAGE ACADEMY</span><span class="edition">CHOOSE CAREER MODE OR ARCADE MODE</span>${button('PLAY ARCADE MODE','start-arcade','arcade-nav-button')}</div><main id="main" class="title-home-main" tabindex="-1">${crewHeroMarkup()}<div class="title-content"><div class="eyebrow"><span class="live-dot"></span> TWO WAYS TO PLAY</div><p class="title-kicker">FINANCIAL FREEDOM</p><h1>MONEY<br><span>OPS.</span></h1><p class="title-description">Build <strong>Moneybread City in Career Mode</strong> or jump into temporary <strong>Arcade play</strong> with every level unlocked.</p><section class="mode-entry-grid" aria-label="Choose a game mode"><article class="mode-entry-card career-entry"><span>SAVES PROGRESS</span><h2>CAREER MODE</h2><p>Earn bread to run the city. Learn through 32 original lessons, choose work, plan your bread, and build your saved Moneybread City.</p>${careerProfile?button('CONTINUE CAREER →','continue-career','primary'):'<a class="mode-jump" href="#profile-form">CREATE CAREER ↓</a>'}</article><article class="mode-entry-card arcade-entry"><span>NO SAVE FILE</span><h2>ARCADE MODE</h2><p>Play any runner level, collect coins, and build a temporary Grand Financial City. Town progress resets when you leave Arcade; the high-score board stays on this device.</p><button class="primary" type="button" data-action="start-arcade">PLAY ARCADE MODE →</button></article></section>${careerProfile?`<section class="homepage-save"><h2>Welcome back, ${escape(careerProfile.name)}.</h2><p>Your Career progress is saved on this device. Continue where you left off, or choose Arcade Mode above.</p>${button('CONTINUE CAREER →','continue-career','primary')}</section>`:`<div class="career-form-heading" id="career-setup"><span>CAREER MODE SETUP · SAVES PROGRESS</span><p>Create the hero whose complete financial journey you want this device to remember.</p></div><div class="career-promise" aria-label="Career mode journey"><span><b>$0</b>START</span><i>→</i><span><b>32</b>LESSONS</span><i>→</i><span><b>$$$</b>BUILD</span></div><form id="profile-form"><label for="name">PLAYER NAME</label><input id="name" name="name" maxlength="24" placeholder="Enter your name" autocomplete="off" required><fieldset class="character-picker"><legend>1 · CHOOSE YOUR CAREER HERO</legend>${castIds.map((id,i)=>`<label class="character-option"><input type="radio" name="avatar" value="${id}" ${i===0?'checked':''}><span>${portrait(id,'creator-character')}<b>${characters[id].name}</b><small>${characters[id].role}</small></span></label>`).join('')}</fieldset><fieldset class="color-picker"><legend>2 · CHOOSE YOUR TEAM COLOR</legend>${colors.map((color,i)=>`<label><input type="radio" name="accent" value="${color}" ${i===0?'checked':''}><span style="--swatch:${color}"></span></label>`).join('')}</fieldset><fieldset><legend>3 · CHOOSE YOUR MISSION BADGE</legend>${['◈','↗','⌁','◎'].map((a,i)=>`<label class="emblem"><input type="radio" name="emblem" value="${a}" ${i===0?'checked':''}><span>${a}</span></label>`).join('')}</fieldset><button class="primary" type="submit">START CAREER MODE <span>↗</span></button></form><p class="fine">1 persistent hero · $0 starting balance · 32 connected lessons · automatic local saving</p>`}${storageWarning?`<p class="warning" role="alert">${storageWarning}</p>`:''}</div><div class="title-coordinate">BUILD YOUR CHARACTER <span>CAREER READY</span></div></main><footer>${castIds.map(id=>portrait(id,'title-footer-character')).join('')}<span>EARN → SAVE → INVEST → FREEDOM</span>${button('PLAY ARCADE MODE','start-arcade','arcade-nav-button')}</footer></div>`;}
function missionCards(){return `<div class="section-title"><h2>YOUR MISSIONS</h2><span>${String(missions.length).padStart(2,'0')} CONNECTED MISSIONS</span></div><div class="mission-grid">${missions.map(m=>{const done=p.completed.includes(m.id);const locked=p.moneybread?!canOpen(p.moneybread,m.id):!done&&m.id>1&&!p.completed.includes(m.id-1);const terms=(m.concepts||m.topic.split(' • ')).slice(0,3).join(' · ');return `<article class="mission-card mission-${m.id} ${locked?'locked':''}"><div class="card-top"><span class="eyebrow">MISSION ${String(m.id).padStart(2,'0')}</span><span class="tag ${done?'complete':''}">${done?'✓ COMPLETED':locked?'◇ LOCKED':'● AVAILABLE'}</span></div><div class="mission-art"><span>${m.icon}</span><i></i><i></i><i></i></div><div class="mission-copy"><small>${m.location||m.sector}</small><h3>${m.title}</h3><p>${m.topic}</p><div class="mission-bottom"><span>${terms}</span>${button(done?'Replay ↻':locked?`Complete Mission ${String(m.id-1).padStart(2,'0')}`:'Play ↗',`begin-${m.id}`,'card-button',locked?'disabled':'')}</div></div></article>`;}).join('')}</div>`;}
function badgePanel(){return `<section class="panel badges"><div class="section-title"><h2>YOUR BADGES</h2><span>${p.badges.length} / ${badges.length}</span></div><div class="badge-grid">${badges.map(b=>`<div class="badge ${p.badges.includes(b.id)?'earned':''}"><span class="badge-icon">${b.icon}</span><strong>${b.name}</strong><small>${b.detail}</small><em>${p.badges.includes(b.id)?'UNLOCKED':'LOCKED'}</em></div>`).join('')}</div></section>`;}
function map(){return `<h1>COMPLETE CAREER MAP</h1><p class="play-prompt">Your chosen hero carries one financial life through all 32 lessons. Every completed lesson saves career progress, savings, investments, and decisions.</p>${missionCards()}`;}
function history(){const worth=netWorth(p),totals=[['Cash + checking',p.cash+p.checking],['Savings + emergency fund',p.savings+p.emergencyFund],['Investments + stocks + ETFs',p.investments+p.stocks+p.etfs],['Property + business + other assets',p.property+p.businessValue+p.assets+p.otherAssets],['Debt + loans',p.debt+p.loans],['Monthly income',p.monthlyIncome],['Monthly expenses',p.monthlyExpenses],['Giving / impact',p.giving],[worth<0?'Debt above assets':'Net worth',Math.abs(worth)]];return `<section class="panel"><div class="section-title"><h2>MY FINANCIAL STORY</h2><span>SIMULATED DOLLARS</span></div><div class="ledger">${totals.map(([k,v],index)=>`<div class="${index===totals.length-1&&worth<0?'negative-position':''}"><span>${k}</span><b>${money(v)}</b></div>`).join('')}<div><span>Credit score</span><b>${p.creditScore}</b></div></div><p class="muted">${worth<0?'You currently owe more than the value of the things you own. The amount above shows the difference without a confusing minus sign.':'Net worth equals everything you own minus everything you owe.'} Market returns and life events in Money Ops are simulations, not promises.</p><h3>DECISION HISTORY</h3>${p.history.length?p.history.map(h=>{const past=Number(h.worth)||0;return `<div class="history-row"><span>MISSION ${String(h.mission).padStart(2,'0')}${h.practice?' / PRACTICE':''}<b>${escape(h.title||h.choice)}</b><small>${escape(h.choice)}</small></span><span>${money(Math.abs(past))} ${past<0?'debt above assets':'net worth'}<small>${money(h.borrowed)} new debt</small></span></div>`;}).join(''):'<p class="muted">Your first decision starts the story.</p>'}</section>`;}
function teacherView(){const summary=studentSummary(p);return `<section class="panel teacher-view"><div class="section-title"><h2>TEACHER PROGRESS VIEW</h2><span>LOCAL STUDENT PROFILE</span></div><p>This view reports participation and lesson completion. Arcade scores are not financial literacy grades.</p><div class="teacher-summary"><span>LESSONS COMPLETE<b>${summary.missionsCompleted}/32</b></span><span>PRE-RUNS PLAYED<b>${summary.preRunsCompleted}</b></span><span>BONUS RUNS PLAYED<b>${summary.bonusRunsCompleted}</b></span><span>LESSON XP<b>${summary.xp}</b></span><span>ARCADE XP<b>${summary.arcadeXp}</b></span><span>ACTIVITY RESULTS<b>${Object.keys(p.missionMedals||{}).length}</b></span></div><div class="teacher-week-table"><div><b>WEEK</b><b>LESSON</b><b>PRE-RUN</b><b>LESSON</b><b>BONUS</b><b>ACTIVITY</b></div>${missions.map(m=>{const run=runnerProgress(p,m.id),done=p.completed.includes(m.id);return `<div><span>${m.id}</span><span>${escape(m.title)}</span><span>${run.pre.completed?(run.pre.skipped?'SKIPPED':'PLAYED'):'—'}</span><span>${done?'COMPLETE':run.lessonStarted?'STARTED':'—'}</span><span>${run.post.completed?(run.post.skipped?'SKIPPED':'PLAYED'):'—'}</span><span>${escape(p.missionMedals?.[m.id]||'—')}</span></div>`;}).join('')}</div><p class="muted">Student information stays in this local profile and is not placed on a public leaderboard.</p></section>`;}
function settings(){return `<section class="panel settings"><div class="eyebrow">SAVED CAREER PROFILE</div><h1>YOUR CAREER.</h1><p>Your hero, current lesson, scores, savings, investments, and decisions save after every action in this browser. Use CONTINUE CAREER to resume an unfinished lesson.</p><form id="rename-form"><label for="rename">PLAYER NAME</label><input id="rename" name="name" maxlength="24" required value="${escape(p.name)}"><button class="primary">UPDATE NAME</button></form><div class="audio-settings"><label for="music-volume">MUSIC VOLUME <output>${Math.round(p.musicVolume*100)}%</output></label><input id="music-volume" data-setting="musicVolume" type="range" min="0" max="1" step="0.05" value="${p.musicVolume}"><label for="sfx-volume">SFX VOLUME <output>${Math.round(p.sfxVolume*100)}%</output></label><input id="sfx-volume" data-setting="sfxVolume" type="range" min="0" max="1" step="0.05" value="${p.sfxVolume}"></div>${button(p.muted?'ENABLE AUDIO':'MUTE AUDIO','mute','secondary')}${button('Export career save ↓','export','secondary')}<p class="muted">Export creates a local backup of the complete Career Mode profile.</p><hr><h2>NEW CAREER / RESET PROFILE</h2><p>Reset removes this device's current hero, choices, lessons, and financial portfolio.</p>${resetting?`<div class="warning">This clears your complete career.${button('Keep my career','cancel-reset','secondary')}${button('Start a new financial life','confirm-reset','danger')}</div>`:button('Reset career','reset','secondary')}</section>`;}
function base(){
 if(tab==='operations')return `${header()}${p.cityLoadError?`<main id="main" class="mb-shell" tabindex="-1"><h1>Your city save needs review</h1><p role="alert">${escape(p.cityLoadError)}</p>${button('Export complete Career backup','export','secondary')}${button('Reset city only · preserve lessons','mb-repair-request','secondary')}${cityUI.reset?button('Confirm city reset','mb-repair-confirm','danger'):''}</main>`:renderCity(p,cityUI)}${storageWarning?`<p role="alert" class="warning">${storageWarning}</p>`:''}${arcadeFooter()}`;
 const content=tab==='map'?map():tab==='honors'?badgePanel():tab==='ledger'?history():tab==='teacher'?teacherView():settings();
 return `${header()}<div class="layout">${profile()}<main id="main" tabindex="-1"><nav class="tabs" aria-label="Career sections">${[['operations','CAREER HOME'],['map','CAREER MAP'],['honors','ACHIEVEMENTS'],['ledger','MY PORTFOLIO'],['teacher','TEACHER VIEW']].map(([id,label])=>button(label,`tab-${id}`,tab===id?'active':'',`aria-current="${tab===id?'page':'false'}"`)).join('')}</nav>${p.lastReward?`<div class="reward" role="status">${p.lastReward.rankUp?`◆ RANK UP: ${p.lastReward.rankUp.toUpperCase()} · `:'✓ LESSON SAVED · '}${p.lastReward.xp?`+${p.lastReward.xp} XP`:'Practice complete — career finances preserved'}${button('Dismiss','dismiss','text-button')}</div>`:''}${p.active?`<div class="reward">CAREER LESSON ${String(p.active.id).padStart(2,'0')} IN PROGRESS${button('CONTINUE CAREER →',`begin-${p.active.id}`,'text-button')}</div>`:''}${content}${storageWarning?`<p role="alert" class="warning">${storageWarning}</p>`:''}</main></div>${arcadeFooter()}`;
}
function mission(){return `${header()}<div class="reader-control">${button('🔊 READ THIS SCREEN','read-aloud','secondary')}</div><main id="main" class="mission-main" tabindex="-1">${visualMission(p,button,escape)}</main>${arcadeFooter()}`;}
function runnerIntro(config){
 const post=config.phase==='post',arcade=p.mode==='arcade',characterId=runnerCharacterId(),lead=characters[characterId]?.name||p.name,intensity=arcadeIntensity(),rookie=arcade&&intensity.id==='rookie';
 return `<section class="runner-intro ${post?'runner-bonus-intro':''}">${arcade?'<div class="arcade-run-warning"><b>ARCADE MODE · NOT SAVED</b><span>This run will not change or save to Career Mode.</span></div>':''}<div class="runner-intro-character">${playerPortrait('runner-guide-character',characterId)}<div class="runner-guide-bubble"><small>${escape(lead).toUpperCase()} RUNS THIS LEVEL</small><h1>${arcade?'READY FOR ARCADE MODE?':post?'KNOWLEDGE UNLOCKED — BONUS RUN!':'READY FOR THE FINANCIAL RUNNER?'}</h1><p>Collect <strong>${config.targetCoins} coins</strong> ${config.continueAfterGoal?'to meet the goal, then keep running while lives remain or finish to bank rewards':'to clear Level '+config.lessonId}. ${rookie?'Rookie pace stays slow from start to finish.':arcade?`${escape(intensity.label)} starts at ${intensity.level}× intensity and gets faster every 20 coins.`:'The run begins slowly and gets faster every 20 coins.'} Large labeled hazards show what to jump, while the vocabulary stream explains the words beside the playfield.</p></div></div>${!arcade?`<fieldset class="character-picker runner-character-picker"><legend>CHOOSE YOUR RUNNER</legend>${castIds.map(id=>`<label class="character-option"><input type="radio" name="runner-character" value="${id}" ${id===characterId?'checked':''}><span>${portrait(id,'creator-character')}<b>${characters[id].name}</b></span></label>`).join('')}</fieldset>`:''}<div class="runner-brief-grid"><article><span>ENVIRONMENT</span><b>${escape(config.environmentData.name)}</b></article><article><span>LEVEL GOAL</span><b>${config.targetCoins} COINS${config.continueAfterGoal?' + CONTINUE':''}</b></article><article><span>LIVES</span><b>❤️ ❤️ ❤️${config.extraLifeInterval?' · ♥ PICKUPS, UP TO 5':''}</b></article><article><span>${arcade?'INTENSITY':post?'POWER-UP':'SPEED'}</span><b>${arcade?`${escape(intensity.label)} · LEVEL ${intensity.level}`:post?escape(config.powerUp.name):'5 STAGES'}</b></article></div><div class="runner-preview"><div><small>AVOID OR STOMP</small>${config.obstacleSet.map(item=>`<span class="runner-chip hazard">${item.icon} ${escape(item.label)}</span>`).join('')}</div><div><small>COLLECT</small>${config.collectibleSet.map(item=>`<span class="runner-chip reward">${item.icon} ${escape(item.label)}</span>`).join('')}<span class="runner-chip reward">$? MONEY BOX</span>${config.extraLifeInterval?'<span class="runner-chip reward">♥ EXTRA LIFE</span>':''}</div></div><div class="runner-vocab-preview"><small>WORDS IN THIS LEVEL</small>${config.vocabulary.map(item=>`<span>${escape(item.term)}</span>`).join('')}</div><div class="runner-actions">${button(arcade?'START ARCADE RUN →':post?'START BONUS RUN →':'START PRE-LESSON RUN →','runner-start','primary')}${button(arcade?'BACK TO ARCADE LEVELS':post?'SKIP BONUS RUN':'START LESSON NOW',arcade?'arcade-back':'runner-skip','secondary')}</div><p class="runner-note">${arcade?'Arcade town progress and rewards are temporary. Initials and top scores stay on this device.':'Money Box dollars go into the saved Bonus Wallet after a lesson bonus run.'}</p></section>`;
}
function runnerActive(config){const arcade=p.mode==='arcade';return `<section class="runner-play" aria-label="Financial Freedom Runner"><div class="runner-hud"><span>LIVES <b data-runner-hud="lives">❤️ ❤️ ❤️</b></span><span>COIN GOAL <b data-runner-hud="goal">0 / ${config.targetCoins}</b></span><span>PAYCHECKS <b data-runner-hud="paychecks">0</b></span><span>BONUS <b data-runner-hud="bonus">$0</b></span><span>SPEED <b data-runner-hud="speed">1 / 5</b></span><span>XP <b data-runner-hud="xp">0</b></span><span>SCORE <b data-runner-hud="score">0</b></span></div><div class="runner-power-status" data-runner-hud="power" aria-live="polite"></div><div class="runner-game-grid"><canvas id="runner-canvas" tabindex="0" aria-label="Side-scrolling financial vocabulary runner. Collect ${config.targetCoins} coins.${config.continueAfterGoal?' Continue while lives remain or finish to bank rewards. Collect hearts for extra lives.':''} Space or up arrow jumps. Hold Down arrow to duck; release to stand. P or Escape pauses."></canvas><aside class="runner-vocab-feed" aria-label="Lesson vocabulary stream"><small>LIVE VOCABULARY · WEEK ${String(config.lessonId).padStart(2,'0')}</small><div class="runner-vocab-current"><em data-vocab-action>RUN TO REVEAL</em><b data-vocab-term>${escape(config.vocabulary[0]?.term||config.title)}</b><p data-vocab-definition>${escape(config.vocabulary[0]?.definition||'Collect rewards and clear hazards to reveal lesson words.')}</p></div><div class="runner-vocab-history" data-vocab-history></div></aside></div><div class="runner-touch-controls"><button data-action="runner-jump" aria-label="Jump">↑<span>JUMP</span></button><button data-action="runner-duck" aria-label="Hold to duck; release to stand" aria-pressed="false">↓<span>HOLD TO DUCK</span></button><button data-action="runner-pause" aria-label="Pause or resume">II<span>PAUSE</span></button></div><div class="runner-help"><span>COLLECT ${config.targetCoins} COINS${config.continueAfterGoal?' · THEN KEEP RUNNING':''}</span><span>READ THE VOCAB STREAM</span><span>HOLD ↓ DUCK · P / ESC PAUSE</span><div class="runner-end-actions">${button('RESTART RUN','runner-restart','text-button')}${button(arcade?'END ARCADE RUN':config.phase==='post'?'END BONUS RUN':'FINISH RUN & START LESSON','runner-finish-now','text-button')}</div></div></section>`;}
function resultMetric(label,value,comparison=''){return `<span><small>${label}</small><b>${value}</b>${comparison?`<em>${comparison}</em>`:''}</span>`;}
function runnerVocabularyResults(config,result){const seen=new Set(result.vocabularySeen||[]);return `<section class="runner-vocabulary-results"><div class="section-title"><h2>LEVEL ${String(config.lessonId).padStart(2,'0')} VOCABULARY</h2><span>${seen.size} WORD${seen.size===1?'':'S'} REINFORCED THIS RUN</span></div><div>${config.vocabulary.map(item=>`<article class="${seen.has(item.term)?'seen':''}"><span>${seen.has(item.term)?'✓':'○'}</span><div><b>${escape(item.term)}</b><p>${escape(item.definition)}</p></div></article>`).join('')}</div></section>`;}
function bonusWalletPanel(){const wallet=p.bonusWallet||{available:0,saved:0,invested:0,budgeted:0,items:[]},owned=wallet.items||[];return `<section class="bonus-wallet"><div class="section-title"><h2>BONUS MONEY PLAN</h2><span>GAME DOLLARS · SAVED WITH CAREER</span></div><div class="bonus-wallet-totals"><span>AVAILABLE<b>${money(wallet.available||0)}</b></span><span>SAVED<b>${money(wallet.saved||0)}</b></span><span>INVESTED<b>${money(wallet.invested||0)}</b></span><span>BUDGETED<b>${money(wallet.budgeted||0)}</b></span></div><p>Choose a home for each $5 bundle, or buy an item. Bonus dollars are a game reward and stay separate from simulated net worth.</p><div class="bonus-plan-actions">${button('SAVE $5','bonus-allocate-saved','secondary',wallet.available>=5?'':'disabled')}${button('INVEST $5','bonus-allocate-invested','secondary',wallet.available>=5?'':'disabled')}${button('PUT $5 IN MY BUDGET','bonus-allocate-budgeted','secondary',wallet.available>=5?'':'disabled')}</div><div class="bonus-shop">${bonusItems.map(item=>`<article class="${owned.includes(item.id)?'owned':''}"><span>${item.icon}</span><h3>${item.name}</h3><p>${item.detail}</p>${owned.includes(item.id)?'<b>OWNED · ACTIVE</b>':button(`BUY ${money(item.price)}`,`bonus-buy-${item.id}`,'primary',wallet.available>=item.price?'':'disabled')}</article>`).join('')}</div></section>`;}
function runnerTownDeposit(result){const checks=Number(result.paychecks)||0,pay=Number(result.paycheckCoins)||0,other=Math.max(0,(Number(result.collected)||0)-checks),total=Number.isFinite(result.cityCoins)?result.cityCoins:other+pay;return `<section class="runner-town-deposit" aria-label="Run earnings deposited into your town"><small>PAYCHECKS → BUILD YOUR TOWN</small><h2>${checks} paychecks collected</h2><p>${pay} city coins from paychecks + ${other} from other collected tokens = <strong>${total} city coins deposited</strong>.</p><p>Paychecks count once in this total. Spend these coins on construction below. Money Box bonus dollars remain separate.</p>${result.extraLivesCollected?`<p>Extra lives collected: ${result.extraLivesCollected}</p>`:''}</section>`;}
function runnerResults(config){
 const result=p.runnerSession?.result||runnerProgress(p,config.lessonId)[config.phase],comparison=runnerComparison(p,config.lessonId),post=config.phase==='post',characterId=runnerCharacterId();
 const cityBuilder=cityBuilderMarkup(p,button,escape,{compact:true});
 const change=value=>`${value>=0?'+':''}${value}`;
 if(p.mode==='arcade')return `<section class="runner-results arcade-results"><div class="arcade-run-warning"><b>ARCADE RESULT · NOT SAVED</b><span>Your Career Mode progress and money were not changed.</span></div><div class="runner-result-character">${playerPortrait('runner-result-hero',characterId)}<div><span class="eyebrow">LEVEL ${String(config.lessonId).padStart(2,'0')} COMPLETE</span><h1>${result.collected>=config.targetCoins?`${config.targetCoins}-COIN GOAL COMPLETE!`:'ARCADE RUN COMPLETE!'}</h1><p>Review the lesson words you reinforced, play again, or choose another level.</p></div></div><div class="runner-result-grid">${resultMetric('GOAL',`${result.collected}/${config.targetCoins}`)}${resultMetric('PAYCHECKS',result.paychecks||0)}${resultMetric('BONUS',money(result.bonusMoney))}${resultMetric('SCORE',result.score)}${resultMetric('XP',result.xp)}${resultMetric('AVOIDED',result.avoided)}${resultMetric('TIME',`${result.survivalSeconds}s`)}</div>${arcadeScorePanel(config,result)}${result.collected>=config.targetCoins?'<section class="arcade-town-unlocked"><span>🏗️</span><div><small>TOWN BUILDING FUNDS READY</small><h2>BUILD YOUR OWN TOWN!</h2><p>Your run earnings are in the City Bank. Choose one town building below and build its next stage.</p></div></section>':''}${runnerTownDeposit(result)}${cityBuilder}${runnerVocabularyResults(config,result)}<p class="runner-reflection">Top scores stay on this device. Arcade town construction and rewards reset when you leave Arcade Mode and never change Career Mode.</p><div class="runner-actions">${button('PLAY THIS LEVEL AGAIN','arcade-replay','primary')}${button('CHOOSE ANOTHER LEVEL','arcade-back','secondary')}${button(careerProfile?'RETURN TO SAVED CAREER':'EXIT ARCADE MODE','arcade-exit','secondary')}</div></section>`;
 return `<section class="runner-results"><div class="runner-result-character">${playerPortrait('runner-result-hero',characterId)}<div><span class="eyebrow">${post?'BONUS RUN COMPLETE':'MISSION COMPLETE'}</span><h1>${result.collected>=config.targetCoins?`${config.targetCoins}-COIN GOAL COMPLETE!`:post?'BONUS RUN FINISHED':'TIME TO LEVEL UP YOUR KNOWLEDGE.'}</h1><p>${post?`${escape(config.reflection)} Money Boxes added ${money(result.bonusMoney)} to your Bonus Wallet.`:`You collected ${result.collected} of ${config.targetCoins} coins. Review the vocabulary, then learn how ${escape(config.title)} connects to your financial future.`}</p></div></div>${post?`<div class="runner-comparison" aria-label="Pre and post lesson runner comparison"><div><span>RESULT</span><b>PRE-LESSON</b><b>POST-LESSON</b></div>${[['Score',comparison.pre.score,comparison.post.score],['Goal coins',comparison.pre.collected,comparison.post.collected],['Paychecks',comparison.pre.paychecks||0,comparison.post.paychecks||0],['Paycheck city coins',comparison.pre.paycheckCoins||0,comparison.post.paycheckCoins||0],['Obstacles avoided',comparison.pre.avoided,comparison.post.avoided],['Bonus dollars',money(comparison.pre.bonusMoney),money(comparison.post.bonusMoney)],['XP earned',comparison.pre.xp,comparison.post.xp],['Power-ups used',comparison.pre.powerUpsUsed,comparison.post.powerUpsUsed]].map(row=>`<div><span>${row[0]}</span><b>${row[1]}</b><b>${row[2]}</b></div>`).join('')}</div>`:`<div class="runner-result-grid">${resultMetric('GOAL',`${result.collected}/${config.targetCoins}`)}${resultMetric('PAYCHECKS',result.paychecks||0)}${resultMetric('BONUS',money(result.bonusMoney))}${resultMetric('SCORE',result.score)}${resultMetric('XP',result.xp)}${resultMetric('AVOIDED',result.avoided)}${resultMetric('TIME',`${result.survivalSeconds}s`)}</div>`}${runnerVocabularyResults(config,result)}${runnerTownDeposit(result)}${cityBuilder}${post?bonusWalletPanel():''}<p class="runner-reflection">Runner performance is vocabulary practice and encouragement. It is not a financial literacy grade.</p><div class="runner-actions">${post?button('CONTINUE CAREER →','runner-continue','primary'):button('START LESSON →','runner-start-lesson','primary')}${post?button('PLAY BONUS AGAIN','runner-replay','secondary'):''}</div></section>`;
}
function runner(){const session=p.runnerSession,config=runnerConfig(session.lessonId,session.phase),env=config.environmentData,arcade=p.mode==='arcade',characterId=runnerCharacterId(),intensity=arcadeIntensity();const content=session.status==='playing'?runnerActive(config):session.status==='results'?runnerResults(config):runnerIntro(config);return `${header()}<main id="main" class="runner-shell" style="--runner-sky:${env.sky};--runner-accent:${env.accent}" tabindex="-1"><div class="runner-titlebar"><span>${arcade?`ARCADE MODE · ${escape(intensity.label)} LEVEL ${intensity.level} · NOT SAVED`:`WEEK ${String(config.lessonId).padStart(2,'0')} · ${config.phase==='post'?'BONUS RUN':'PRE-LESSON RUN'}`}</span><b>${escape(config.levelName)} · ${escape(config.title)} · ${escape(characters[characterId].name)}</b></div>${content}</main>${arcadeFooter()}`;}
const counterValues=new Map();
let lastVocabSerial=0;
function animateMoney(){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 app.querySelectorAll('[data-money]').forEach(el=>{const target=Number(el.dataset.money),key=el.dataset.counter,start=counterValues.get(key)??target;counterValues.set(key,target);if(reduced||start===target)return;const t=performance.now();function frame(now){if(!el.isConnected)return;const fraction=Math.min(1,(now-t)/450);el.textContent=money(Math.round(start+(target-start)*(1-(1-fraction)**3)));if(fraction<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);});
}
const traceArrow={ArrowLeft:'←',ArrowRight:'→',ArrowUp:'↑',ArrowDown:'↓'};
function traceDirection(path,length,index,total,step=1){const from=path.getPointAtLength(length*index/(total-1)),to=path.getPointAtLength(length*Math.min(total-1,index+step)/(total-1)),dx=to.x-from.x,dy=to.y-from.y;return Math.abs(dx)>=Math.abs(dy)?dx>=0?'ArrowRight':'ArrowLeft':dy>=0?'ArrowDown':'ArrowUp';}
function updateTraceHint(board,index,total){const hint=board.closest('.trace-activity')?.querySelector('[data-trace-next]');if(!hint)return;const path=board.querySelector('.trace-guide'),length=path?.getTotalLength()||0;hint.textContent=index>=total-1?'✓':traceArrow[traceDirection(path,length,index,total,3)];}
function setTraceProgress(board,index,total=64){if(!board?.isConnected)return;const path=board.querySelector('.trace-guide'),length=path?.getTotalLength()||0,safe=Math.max(0,Math.min(total-1,index)),progress=safe/(total-1),target=path.getPointAtLength(length*safe/(total-1));board.dataset.traceIndex=String(safe);board.dataset.traceTotal=String(total);const ink=board.querySelector('.trace-ink'),cursor=board.querySelector('.trace-cursor');ink.style.strokeDashoffset=length*(1-progress);cursor.setAttribute('cx',target.x);cursor.setAttribute('cy',target.y);board.closest('.trace-activity')?.querySelector('.trace-meter i')?.style.setProperty('width',`${Math.round(progress*100)}%`);const label=board.closest('.trace-activity')?.querySelector('.trace-meter b');if(label)label.textContent=`${Math.round(progress*100)}% TRACED`;updateTraceHint(board,safe,total);if(progress>=.94&&board.dataset.traceComplete!=='true'){board.dataset.traceComplete='true';completeArtTrace(Number(board.dataset.traceTool));}}
function initializeTraceBoards(){app.querySelectorAll('.trace-board').forEach(board=>{const path=board.querySelector('.trace-guide'),start=path?.getPointAtLength(0),length=path?.getTotalLength()||0;if(!start)return;for(const selector of ['.trace-start','.trace-cursor']){const dot=board.querySelector(selector);dot?.setAttribute('cx',start.x);dot?.setAttribute('cy',start.y);}const ink=board.querySelector('.trace-ink');if(ink)ink.style.strokeDasharray=length;board.dataset.traceComplete='false';setTraceProgress(board,0,64);});}
function completeArtTrace(tool){if(p?.active?.id!==1||p.active.project!=='product'||p.active.traceTool!==tool)return;const next=playAction(p,`work-${tool}`);if(next)commit(next,next.active.step==='debrief'?'earn':'success');}
function traceLocation(board,event){const point=board.createSVGPoint();point.x=event.clientX;point.y=event.clientY;return point.matrixTransform(board.getScreenCTM().inverse());}
function advanceTrace(event){const session=activeTrace;if(!session||session.pointerId!==event.pointerId||!session.board.isConnected)return;const point=traceLocation(session.board,event),path=session.path;let best=-1;for(let i=session.index;i<Math.min(session.total,session.index+9);i++){const target=path.getPointAtLength(session.length*i/(session.total-1));if(Math.hypot(point.x-target.x,target.y-point.y)<48)best=i;}if(best<0)return;session.index=best+1;setTraceProgress(session.board,session.index,session.total);}
function fixArrowIcons(){
 const targets=app.querySelectorAll('button,.mission-art,.badge-icon,.honor-icons,.brand-mark');
 targets.forEach(el=>{const walk=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())if(walk.currentNode.textContent.includes('↗'))nodes.push(walk.currentNode);nodes.forEach(node=>{const fragment=document.createDocumentFragment();node.textContent.split('↗').forEach((text,i)=>{if(i){const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('viewBox','0 0 24 24');icon.setAttribute('aria-hidden','true');icon.setAttribute('class','arrow-icon');icon.innerHTML='<path d="M4 20L20 4M5 4h15v15" fill="none" stroke="currentColor" stroke-width="2"/>';fragment.append(icon);}fragment.append(document.createTextNode(text));});node.replaceWith(fragment);});});
}
function updateRunnerVocabulary(event){if(!event||event.serial===lastVocabSerial)return;lastVocabSerial=event.serial;const current=app.querySelector('.runner-vocab-current'),action=app.querySelector('[data-vocab-action]'),term=app.querySelector('[data-vocab-term]'),definition=app.querySelector('[data-vocab-definition]'),history=app.querySelector('[data-vocab-history]');if(!current||!action||!term||!definition||!history)return;action.textContent=`${event.action}: ${event.object}`;term.textContent=event.term;definition.textContent=event.definition;current.classList.remove('vocab-pop');void current.offsetWidth;current.classList.add('vocab-pop');const item=document.createElement('span');item.textContent=event.term;history.prepend(item);while(history.children.length>4)history.lastElementChild.remove();}
function updateRunnerHud(state){const value=(name,text)=>{const node=app.querySelector(`[data-runner-hud="${name}"]`);if(node)node.textContent=text;};value('lives',Array.from({length:state.lifeCap||3},(_,index)=>index<state.lives?'❤️':'♡').join(' '));value('goal',`${state.collected} / ${state.targetCoins}`);value('paychecks',String(state.paychecks||0));value('bonus',money(state.bonusMoney));value('speed',state.intensityLevel===0?'LEVEL 0 · SLOW':`${state.speedStage} / 5`);value('xp',state.xp);value('score',state.score);value('power',state.paused?'PAUSED · GOAL WAITS':state.goalReached?'GOAL MET · KEEP RUNNING OR FINISH TO BANK REWARDS':state.powerUp?`${state.powerUp} ACTIVE!`:state.collected&&state.collected%20===0?'SPEED UP!':state.combo>=3?`${state.combo}× COMBO!`:'');if(state.goalReached){const finish=app.querySelector('[data-action="runner-finish-now"]');if(finish)finish.textContent='BANK REWARDS & FINISH';}updateRunnerVocabulary(state.vocabEvent);}
function initializeRunner(){const session=p?.runnerSession,canvas=app.querySelector('#runner-canvas');if(!session||session.status!=='playing'||!canvas)return;lastVocabSerial=0;const config=runnerConfig(session.lessonId,session.phase);runnerGame=new FinancialRunner(canvas,config,{characterId:runnerCharacterId(session),ownedItems:p.mode==='career'?p.bonusWallet?.items||[]:[],intensityLevel:p.mode==='arcade'?arcadeIntensity().level:1,animateStride:true,onUpdate:updateRunnerHud,onComplete:result=>commit(recordRunnerResult(p,session.lessonId,session.phase,result),'achievement')});runnerGame.bindDuckControl(app.querySelector('[data-action="runner-duck"]'));runnerGame.start(session.startedAt);canvas.focus({preventScroll:true});}
function render(focus=false){runnerGame?.destroy();runnerGame=null;selectedToken=null;activeTrace=null;window.speechSynthesis?.cancel();const view=!showingHome&&p?(p.screen==='runner'&&p.runnerSession?runner():p.mode==='arcade'&&p.screen==='arcade'?arcadeHub():p.screen==='mission'&&p.active?mission():base()):title();app.innerHTML=view+(!showingHome&&p?cityBuildCelebrationMarkup(p,button,escape):'');if(p)app.style.setProperty('--player-accent',p.playerStyle?.accent||'#d9f577');fixArrowIcons();animateMoney();initializeTraceBoards();initializeRunner();if(focus){(document.querySelector('.city-build-modal .primary')||document.querySelector('#main'))?.focus({preventScroll:true});window.scrollTo(0,0);}}
function commit(next,kind='click',focus=true){showingHome=false;p=ensureCareer(next);if(p?.mode!=='arcade'){careerProfile=p;save(p);}sound(kind,p.muted,p.sfxVolume);setMusic(p.muted,p.musicVolume);render(focus);}
function startCareerLesson(profile,id){const marked=markLessonStarted({...profile,runnerSession:null},id),next=begin({...marked,screen:'base'},id);if(id===3&&!next.active.practice)next.active={...next.active,fromEarning:{amount:next.active.wallet.cash,job:'safe'},jobBanked:false};return next;}
function completeCurrentLesson(){const id=p.active?.id,practice=p.active?.practice;if(!id)return;const completed=noteLesson(finish(p),id);if(completed===p||completed.active)return;if(practice){tab='operations';commit(completed,'achievement');return;}const marked=markLessonCompleted(completed,id);commit(openRunner(marked,id,'post'),'achievement');}
app.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);if(e.target.id==='mb-reflect-form'){try{const city=applyCity(p.moneybread,{type:'reflect',text:String(data.get('reflection')||''),term:String(data.get('term')||'')},p.completed);cityUI.error='';cityUI.view='city';commit({...p,moneybread:city},'achievement');}catch(error){cityUI.error=error.message;render(false);document.querySelector('#mb-status')?.focus();}return;}if(e.target.id==='arcade-score-form'){const initials=String(data.get('initials')||'').trim(),result=p.runnerSession?.result;if(!result)return;try{arcadeScores=recordArcadeScore(arcadeScores,{initials,score:result.score,lessonId:p.runnerSession.lessonId,coins:result.collected});p={...p,runnerSession:{...p.runnerSession,scoreRecorded:true,scoreInitials:initials.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,3)}};sound('achievement',p.muted,p.sfxVolume);render(true);}catch{e.target.querySelector('input')?.setCustomValidity('Enter two or three initials.');e.target.reportValidity();}return;}const name=String(data.get('name')||'').trim();if(!name)return;if(e.target.id==='profile-form')commit(newGame(name,String(data.get('avatar')), {accent:String(data.get('accent')),emblem:String(data.get('emblem'))}),'start');if(e.target.id==='rename-form')commit({...p,name});});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(action==='site-home'){showingHome=true;render(true);return;}
 if(action==='continue-career'&&careerProfile){showingHome=false;p=careerProfile;tab='operations';render(true);return;}
 if(action==='start-arcade'){showingHome=false;p=newArcadeProfile(careerProfile?.avatar);sound('start',p.muted,p.sfxVolume);render(true);return;}
 if(!p)return;
 if(performance.now()<suppressClickUntil)return;
 if(action.startsWith('mb-')){
  if(p.mode==='arcade')return;
  if(action==='mb-repair-request'){cityUI.reset=true;render(true);return;}
  if(action==='mb-repair-confirm'){cityUI.reset=false;commit({...p,moneybread:freshCity(p.completed),cityLoadError:null});return;}
  if(action.startsWith('mb-view-')){cityUI.view=action.slice(8);cityUI.preview=undefined;cityUI.error='';tab='operations';commit({...p,screen:'base'});return;}
  if(action.startsWith('mb-district-')){cityUI.district=action.slice(12);cityUI.preview=undefined;render(false);return;}
  if(action.startsWith('mb-preview-')){const id=Number(action.slice(11));if(canOpen(p.moneybread,id)){cityUI.preview=id;cityUI.district=destination(id)?.district||cityUI.district;cityUI.view='city';render(true);document.querySelector('#mb-next-stop-cue')?.focus();}return;}
  if(action==='mb-reset-request'||action==='mb-reset-cancel'){cityUI.reset=action==='mb-reset-request';render(false);document.querySelector('.mb-reset-confirm')?.scrollIntoView({block:'center'});return;}
  let choice;
  if(action.startsWith('mb-work-'))choice={type:'work',job:action.slice(8)};
  if(action.startsWith('mb-allocate-'))choice={type:'allocate',plan:action.slice(12)};
  if(action.startsWith('mb-build-'))choice={type:'build',district:action.slice(9)};
  if(action==='mb-withdraw')choice={type:'withdraw'};
  if(action==='mb-reset-confirm'){choice={type:'reset'};cityUI.reset=false;}
  if(choice)try{const city=applyCity(p.moneybread,choice,p.completed);if(choice.type==='build')cityUI.district=choice.district;cityUI.error='';commit({...p,moneybread:city},choice.type==='work'?'earn':choice.type==='build'?'achievement':'click',false);document.querySelector('.mb-next-task')?.focus({preventScroll:true});}catch(error){cityUI.error=error.message;render(false);}
  return;
 }

 if(action==='read-aloud'){const text=document.querySelector('[data-read]')?.dataset.read||document.querySelector('.play-prompt')?.textContent||'Choose mission one to create value and earn money. Then build income, save, and plan.';if('speechSynthesis' in window){const utterance=new SpeechSynthesisUtterance(text);utterance.rate=.85;window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance);}else document.querySelector('#announcer').textContent='Read aloud is not supported in this browser.';return;}
 if(action==='cheer'){b.classList.remove('cheer');void b.offsetWidth;b.classList.add('cheer');sound('success',p.muted,p.sfxVolume);document.querySelector('#announcer').textContent='Your Money Ops guide is cheering!';return;}
 if(action.startsWith('pop-spark-')){b.classList.add('collected');b.disabled=true;sound('xp',p.muted,p.sfxVolume);document.querySelector('#announcer').textContent='Achievement marker collected!';return;}
 if(action.startsWith('select-')){selectedToken=action.slice(7);app.querySelectorAll('[data-drag]').forEach(el=>{const active=el.dataset.drag===selectedToken;el.classList.toggle('picked',active);el.setAttribute('aria-pressed',String(active));});document.querySelector('#announcer').textContent='Picked up. Now tap its home.';return;}
 if(action.startsWith('drop-')){if(selectedToken)handleDrop(selectedToken,action.slice(5));return;}
 if(action.startsWith('mark-decision-')){const id=action.slice(14);selectedToken=`decision-${id}`;const workbench=b.closest('.decision-workbench'),crossout=workbench?.classList.contains('method-crossout');workbench?.querySelectorAll('.decision-card').forEach(card=>{const selected=card===b;card.classList.toggle('circled',selected);card.classList.toggle('crossed',crossout&&!selected);card.setAttribute('aria-pressed',String(selected));});const confirm=workbench?.querySelector('[data-action="confirm-decision"]');if(confirm)confirm.disabled=false;document.querySelector('#announcer').textContent=crossout?'Other choices crossed out. Your choice is circled. Confirm it.':'Choice circled. Confirm it.';return;}
 if(action==='confirm-decision'&&selectedToken?.startsWith('decision-')){commit(choose(p,selectedToken.slice(9)),'warning');return;}
 if(action==='arcade-open'||action==='arcade-open-header'){if(p.mode==='arcade'){commit({...p,screen:'arcade',runnerSession:null},'click');return;}careerProfile=p;p=newArcadeProfile(p.avatar);commit(p,'start');return;}
 if(action==='arcade-exit'){p=careerProfile||null;tab='operations';render(true);return;}
 if(action.startsWith('arcade-intensity-')){const id=action.slice(17);if(arcadeIntensities.some(item=>item.id===id))commit({...p,arcadeIntensity:id,screen:'arcade'},'click');return;}
 if(action.startsWith('arcade-character-')){const id=action.slice(17);if(castIds.includes(id))commit({...p,avatar:id,screen:'arcade'},'click');return;}
 if(action.startsWith('arcade-level-')){const lessonId=Number(action.slice(13));if(lessonId>=1&&lessonId<=32){const config=runnerConfig(lessonId,'pre');commit({...p,screen:'runner',runnerSession:{lessonId,phase:'pre',status:'intro',startedAt:null,targetCoins:config.targetCoins}},'start');}return;}
 if(action==='arcade-back'){commit({...p,screen:'arcade',runnerSession:null},'click');return;}
 if(action==='arcade-replay'){commit({...p,screen:'runner',runnerSession:{...p.runnerSession,status:'intro',startedAt:null,result:null}},'start');return;}
 if(action==='runner-start'){const startedAt=Date.now();commit({...p,runnerSession:{...p.runnerSession,status:'playing',startedAt}},'start');return;}
 if(action==='runner-skip'){const {lessonId,phase}=p.runnerSession;const skipped=recordRunnerResult(p,lessonId,phase,{skipped:true,reason:'skipped'});if(phase==='post'){tab='operations';commit({...skipped,screen:'base',runnerSession:null},'click');}else commit(skipped,'click');return;}
 if(action==='runner-start-lesson'){const id=p.runnerSession.lessonId;commit(startCareerLesson(p,id),'start');return;}
 if(action==='runner-continue'){tab='operations';commit({...p,screen:'base',runnerSession:null},'click');return;}
 if(action==='runner-replay'){commit(openRunner({...p,runnerSession:null},p.runnerSession.lessonId,'post'),'start');return;}
 if(action==='runner-jump'){runnerGame?.jump();return;}
 if(action==='runner-duck'){if(e.detail===0)runnerGame?.duck();return;}
 if(action==='runner-pause'){runnerGame?.togglePause();return;}
 if(action==='runner-restart'){commit({...p,runnerSession:{...p.runnerSession,status:'playing',startedAt:Date.now()}},'start');return;}
 if(action==='runner-finish-now'){runnerGame?.finish('manual');return;}
 if(action==='dismiss-city-build'){commit({...p,city:{...p.city,celebration:null}},'click',false);return;}
 if(action.startsWith('city-build-')){commit(buildCity(p,action.slice(11)),'achievement');return;}
 if(action.startsWith('bonus-allocate-')){const bucket=action.slice(15),wallet=p.bonusWallet||{available:0,saved:0,invested:0,budgeted:0,items:[]};if(['saved','invested','budgeted'].includes(bucket)&&wallet.available>=5)commit({...p,bonusWallet:{...wallet,available:wallet.available-5,[bucket]:(wallet[bucket]||0)+5}},'coin');return;}
 if(action.startsWith('bonus-buy-')){const id=action.slice(10),item=bonusItems.find(entry=>entry.id===id),wallet=p.bonusWallet||{available:0,saved:0,invested:0,budgeted:0,items:[]},items=wallet.items||[];if(item&&wallet.available>=item.price&&!items.includes(id))commit({...p,bonusWallet:{...wallet,available:wallet.available-item.price,items:[...items,id]}},'achievement');return;}
 const playNext=playAction(p,action);if(playNext){commit(playNext,playNext.active.step==='debrief'?'earn':action.startsWith('save-')?'click':'xp');return;}
 if(action==='mute'){commit({...p,muted:!p.muted},'click',false);document.querySelector('[data-action="mute"]')?.focus();return;}
 if(action.startsWith('tab-')){tab=action.slice(4);commit({...p,screen:'base'});return;}
 if(action==='profile'){tab='profile';render(true);return;}
 if(action.startsWith('begin-')){const id=Number(action.slice(6));if(p.moneybread&&!canOpen(p.moneybread,id)){document.querySelector('#announcer').textContent='Complete the current lesson and weekly city reflection to unlock this level.';return;}if(p.active&&p.active.id===id){commit({...p,screen:'mission'},'start');return;}if(p.active){document.querySelector('#announcer').textContent='Finish your current mission before starting another.';return;}if(p.completed.includes(id)||runnerProgress(p,id).pre.completed){commit(startCareerLesson(p,id),'start');return;}commit(openRunner(p,id,'pre'),'start');return;}
 if(action==='home'){commit({...p,screen:'base'});return;}
 if(action==='next'){const a=p.active;if(a&&['brief','learn'].includes(a.step))commit({...p,active:{...a,step:'choice'}});return;}
 if(action.startsWith('choose-')){commit(choose(p,action.slice(7)),p.active.id===1?'earn':'warning');return;}
 if(action==='resolve'){commit(resolve(p),'loss');return;}
 if(action==='finish-to-plan'&&p.active?.id===1&&p.active.step==='debrief'){completeCurrentLesson();return;}
 if(action==='finish-to-save'&&p.active?.id===2&&p.active.step==='debrief'){completeCurrentLesson();return;}
 if(action==='finish'){completeCurrentLesson();return;}
 if(action==='retry-mission'){const id=p.active?.id;if(!id)return;commit(begin({...p,active:null,screen:'base'},id),'start');return;}
 if(action==='dismiss'){commit({...p,lastReward:null});return;}
 if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='money-ops-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='reset'||action==='cancel-reset'){resetting=action==='reset';render(true);return;}
 if(action==='confirm-reset'){p=null;careerProfile=null;clear();resetting=false;tab='operations';render(true);}
});
render();

app.addEventListener('pointerdown',event=>{const board=event.target.closest('.trace-board');if(!board||event.button!==0)return;event.preventDefault();board.focus({preventScroll:true});board.setPointerCapture(event.pointerId);activeTrace={board,path:board.querySelector('.trace-guide'),length:board.querySelector('.trace-guide').getTotalLength(),index:Number(board.dataset.traceIndex)||0,total:Number(board.dataset.traceTotal)||64,pointerId:event.pointerId};advanceTrace(event);});
app.addEventListener('pointermove',event=>{if(activeTrace){event.preventDefault();advanceTrace(event);}});
app.addEventListener('pointerup',event=>{if(activeTrace?.pointerId===event.pointerId)activeTrace=null;});
app.addEventListener('pointercancel',()=>{activeTrace=null;});
app.addEventListener('keydown',event=>{const board=event.target.closest('.trace-board');if(!board||!traceArrow[event.key]||board.dataset.traceComplete==='true')return;event.preventDefault();const path=board.querySelector('.trace-guide'),length=path.getTotalLength(),total=Number(board.dataset.traceTotal)||64,current=Number(board.dataset.traceIndex)||0,step=Math.min(3,total-1-current),expected=traceDirection(path,length,current,total,step);if(event.key!==expected){board.classList.remove('trace-wrong-key');void board.offsetWidth;board.classList.add('trace-wrong-key');document.querySelector('#announcer').textContent=`Follow the dotted line. Press ${traceArrow[expected]}.`;return;}board.classList.remove('trace-wrong-key');setTraceProgress(board,current+step,total);});

app.addEventListener('input',event=>{
 const input=event.target.closest('[data-setting]');
 if(!input||!p)return;
 const key=input.dataset.setting,value=Math.max(0,Math.min(1,Number(input.value)));
 if(!['musicVolume','sfxVolume'].includes(key)||!Number.isFinite(value))return;
 p={...p,[key]:value};if(p.mode!=='arcade'){careerProfile=p;save(p);}
 input.previousElementSibling?.querySelector('output')?.replaceChildren(`${Math.round(value*100)}%`);
 if(key==='musicVolume')setMusic(p.muted,value);
 else sound('click',p.muted,value);
});

function progressCount(a){
 if(!a)return 0;
 if(a.id===1)return (a.yardPrep||[]).length+(a.workDone||[]).length;
 if(a.step==='event'||a.step==='debrief')return (a.repairDone||[]).length+5;
 return (a.jobBanked?1:0)+(a.planned||0)/250;
}
function handleDrop(token,target){
 const before=p.active,next=dropAction(p,token,target);
 if(!next)return;
 const after=next.active,finished=after.step==='debrief',progressed=progressCount(after)>progressCount(before)||after.step!==before.step||after.traceTool!==before.traceTool;
 let kind='retry';
 if(progressed){
  if(finished)kind=after.id===1?'earn':'achievement';
  else if(token==='earnings-bag'||token.startsWith('coin'))kind='coin';
  else if(token.startsWith('tool-'))kind='repair';
  else kind='success';
 }
 commit(next,kind,finished);
 const stage=app.querySelector('.visual-play');
 stage?.classList.add(progressed?'action-success':'action-retry');
 stage?.querySelector('.journey-buddy')?.classList.add(progressed?'cheer':'oops');
 if(progressed&&!finished){
  let fresh=null;
  if(token==='earnings-bag'||token.startsWith('coin'))fresh=stage?.querySelector('.jar');
  else if(token.startsWith('tool-'))fresh=stage?.querySelector('.car-bay .play-art');
  else if(target==='basket')fresh=stage?.querySelector('.drop-basket');
  else fresh=stage?.querySelector(`[data-drop="${target}"]`);
  fresh?.classList.add('fresh-success');
 }
 const message=finished
  ?after.id===1?'You created value and earned money!':'The car is fixed. See how savings helped.'
  :progressed?(after.hint||'Great move!'):after.hint||'Try its matching home!';
 document.querySelector('#announcer').textContent=message;
}
installDrag(app,(token,target)=>{suppressClickUntil=performance.now()+150;handleDrop(token,target);});

app.addEventListener('error',event=>{const img=event.target;if(img.matches?.('[data-landmark-image]'))img.closest('.city-landmark-art')?.classList.add('art-missing');if(img.matches?.('[data-crew-image]')){const frame=img.closest('.mb-portrait');frame?.querySelector('svg')?.setAttribute('hidden','');const fallback=frame?.querySelector('.mb-portrait-fallback');if(fallback)fallback.hidden=false;}if(img.matches?.('.mb-city-scene')){img.closest('figure')?.classList.add('crew-base-missing');img.hidden=true;const fallback=img.closest('.mb-source-city')?.querySelector('.mb-city-art-fallback');if(fallback)fallback.hidden=false;}if(img.matches?.('.money-ops-reference')){img.closest('figure')?.classList.add('crew-base-missing');img.hidden=true;const fallback=img.closest('.reference-crew-hero')?.querySelector('.crew-image-fallback');if(fallback)fallback.hidden=false;}},true);

app.addEventListener('load',event=>{const img=event.target;if(img.matches?.('.mb-city-scene'))img.closest('.mb-map')?.classList.add('scene-ready');},true);

